"""Private staged-index/bulk-projection diagnostic, not production or acceptance code."""
import json,time
from collections import Counter
from pathlib import Path
from commontrace import fact_store as fs,hierarchical as h
from benchmarks.next_generation_storage import items

original_index=fs.StatementIndex
original_flush=fs.FactMap.flush
class Variants:
 def __init__(self,base,extra):self.base,self.extra=base,extra
 def __iter__(self):return iter(sorted(set(self.base)|set(self.extra)))
 def get(self,key,default=()):return list(dict.fromkeys([*self.base.get(key,()),*self.extra.get(key,())])) or default
 def __getitem__(self,key):return self.get(key)
class Slots:
 def __init__(self,base,extra):self.base,self.extra=base,extra
 def get(self,key,default=None):return Variants(self.base.get(key,{}),self.extra.get(key,{}))
class StagedIndex(original_index):
 def __init__(self,facts):
  super().__init__(facts)
  self.staged={};self.overlay=h._StatementIndex(self.staged)
  self.slots=Slots(self.slots,self.overlay.slots)
 def add(self,fact):
  self.staged[fact.id]=fact;self.overlay.add(fact)
 def exact(self,statement,scopes):
  return super().exact(statement,scopes) or self.overlay.exact(statement,scopes)
 def near(self,statement,scopes,threshold=.85):
  hits=[hit for hit in (super().near(statement,scopes,threshold),self.overlay.near(statement,scopes,threshold)) if hit is not None]
  return min(hits,key=lambda fact:(-fact.confirmations,fact.id)) if hits else None

def chunks(values,size=200):
 for offset in range(0,len(values),size):yield values[offset:offset+size]
def bulk_project(facts):
 connection=facts.connection
 changed=[(fact,fs._dump(fact.to_dict())) for key,fact in facts.loaded.items()
          if key not in facts.removed]
 changed=[(fact,payload) for fact,payload in changed if payload!=facts.before[fact.id]]
 if not changed:return
 keys=[fact.id for fact,_ in changed]
 old_rows=[]
 for group in chunks(keys):
  old_rows.extend(row[0] for row in connection.execute('SELECT rowid FROM facts WHERE id IN ('+','.join('?' for _ in group)+')',group))
 decrements=Counter()
 for group in chunks(old_rows):
  clause='('+','.join('?' for _ in group)+')'
  for term_id,count in connection.execute('SELECT term_id,COUNT(*) FROM postings WHERE fact_row IN '+clause+' GROUP BY term_id',group):decrements[term_id]+=count
  connection.execute('DELETE FROM postings WHERE fact_row IN '+clause,group)
  connection.execute('DELETE FROM fact_fts WHERE rowid IN '+clause,group)
 connection.executemany('UPDATE lexicon SET documents=documents-? WHERE id=?',((count,key) for key,count in decrements.items()))
 prepared=[];terms={};frequencies=Counter()
 for fact,payload in changed:
  norm,block,slot,negative,numbers,content,bm25,overlap=fs._features(fact)
  prepared.append((fact.id,payload,norm,block,slot,negative,numbers,fact.status,int(fact.forgotten),fact.category,fact.confidence,sum(bm25.values())))
  rows=[(kind,term,count) for kind,values in (('near:'+block,{word:1 for word in content}),('overlap-v1',{word:1 for word in overlap}),('bm25-v1',bm25)) for term,count in values.items()]
  terms[fact.id]=rows;frequencies.update((kind,term) for kind,term,_ in rows)
 connection.executemany('INSERT INTO facts VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,norm=excluded.norm,block=excluded.block,slot=excluded.slot,negative=excluded.negative,numbers=excluded.numbers,status=excluded.status,forgotten=excluded.forgotten,category=excluded.category,confidence=excluded.confidence,length=excluded.length',prepared)
 rowids={}
 for group in chunks(keys):
  rowids.update(connection.execute('SELECT id,rowid FROM facts WHERE id IN ('+','.join('?' for _ in group)+')',group))
 connection.executemany('INSERT INTO lexicon(kind,term,documents) VALUES(?,?,?) ON CONFLICT(kind,term) DO UPDATE SET documents=documents+excluded.documents',((kind,term,count) for (kind,term),count in frequencies.items()))
 termids={}
 for group in chunks(list(frequencies)):
  sql='SELECT kind,term,id FROM lexicon WHERE (kind,term) IN (VALUES '+','.join('(?,?)' for _ in group)+')'
  termids.update(((kind,term),identity) for kind,term,identity in connection.execute(sql,[value for pair in group for value in pair]))
 connection.executemany('INSERT INTO postings VALUES(?,?,?)',((termids[kind,term],rowids[key],count) for key,rows in terms.items() for kind,term,count in rows))
 connection.executemany('INSERT INTO fact_fts(rowid,fact_id,statement) VALUES(?,?,?)',((rowids[fact.id],fact.id,fact.statement) for fact,_ in changed))
def flush(self):
 bulk_project(self);original_flush(self)


# Additional private diagnostic: explicit request lifetime, bounded cached features,
# precomputed payload reuse and batched event insertion. Not production code.
import contextvars
from collections import OrderedDict
from dataclasses import asdict,dataclass
from commontrace import fact_conflicts
from commontrace.memory_record import MemoryRecord

CACHE=contextvars.ContextVar('diagnostic_statement_features',default=None)
original_norm=h._normalize_statement;original_signature=h._signature;original_slot=fact_conflicts.slot_key
original_dict=h.AtomicFact.to_dict
class FeatureCache:
 def __init__(self):
  self.values=OrderedDict();self.weight=0;self.hits=0;self.misses=0;self.peak_entries=0;self.peak_weight=0;self.closed=False
 def get(self,kind,text,build):
  if self.closed:return build(text)
  key=(kind,text)
  if key in self.values:
   self.hits+=1;self.values.move_to_end(key);return self.values[key][0]
  self.misses+=1;value=build(text)
  count=sum(len(part) for part in value) if kind=='signature' else len(value)
  weight=len(text)*4+256+count*128
  if weight<=4*1024*1024:
   while self.values and (len(self.values)>=4096 or self.weight+weight>4*1024*1024):
    _,(_,old)=self.values.popitem(last=False);self.weight-=old
   self.values[key]=(value,weight);self.weight+=weight
   self.peak_entries=max(self.peak_entries,len(self.values));self.peak_weight=max(self.peak_weight,self.weight)
  return value
 def close(self):self.closed=True;self.values.clear();self.weight=0

def memo(kind,original):
 def wrapped(text):
  cache=CACHE.get()
  return original(text) if cache is None else cache.get(kind,text,original)
 return wrapped
cached_norm=memo('norm',original_norm);cached_signature=memo('signature',original_signature);cached_slot=memo('slot',original_slot)
@dataclass
class Box:
 value:object
primitive=(str,int,float,bool,type(None))
def fast_dict(self):
 if type(self) is not h.AtomicFact:return asdict(self)
 result={name:value for name,value in vars(self).items() if name in h._FACT_FIELDS}
 for name,value in result.items():
  if type(value) in primitive:continue
  if type(value) is list and all(type(v) in primitive for v in value):result[name]=value.copy()
  elif type(value) is dict and all(type(k) in primitive and type(v) in primitive for k,v in value.items()):result[name]=value.copy()
  else:result[name]=asdict(Box(value))['value']
 return result

# The inspected existing prototype performs final batch projections. Reuse it,
# but supply the already captured payloads instead of serializing every fact twice.
import inspect
bulk_source=inspect.getsource(bulk_project)
bulk_source=bulk_source.replace('def bulk_project(facts):','def bulk_project_prepared(facts,changed):')
left=bulk_source.index(' changed=');right=bulk_source.index(' if not changed:return',left)
bulk_source=bulk_source[:left]+bulk_source[right:]
exec(compile(bulk_source,'<prepared-bulk-projection>','exec'),globals())

def bulk_event_flush(facts):
 changed=[]
 for key,fact in facts.loaded.items():
  if key in facts.removed:
   if facts.before[key] is not None:fs._append(facts.connection,fact,delete=True)
   else:fs._remove_projection(facts.connection,key)
  else:
   payload=fact.to_dict();encoded=fs._dump(payload)
   if encoded!=facts.before[key]:changed.append((fact,payload,encoded))
 if not changed:return
 bulk_project_prepared(facts,[(fact,encoded) for fact,payload,encoded in changed])
 versions={}
 for group in chunks([fact.id for fact,payload,encoded in changed]):
  versions.update(facts.connection.execute('SELECT fact_id,MAX(version) FROM events WHERE fact_id IN ('+','.join('?' for _ in group)+') GROUP BY fact_id',group))
 rows=[]
 for fact,payload,encoded in changed:
  version=versions.get(fact.id,0)+1
  record=MemoryRecord(fact.id,'fact',version,payload,status='active' if fact.status=='active' else 'deprecated',
   relations={'updates':[fact.id]} if version>1 else {},provenance={'source_traces':fact.source_traces},
   scope={'labels':fact.scopes},valid_from=fact.valid_from,valid_until=fact.valid_until,created_at=fact.created_at,
   retracted_at=fact.retracted_at,confidence=fact.confidence,evidence=payload['evidence'])
  rows.append((fact.id,version,'put',fs._dump(vars(record))))
 facts.connection.executemany('INSERT INTO events(fact_id,version,operation,record) VALUES(?,?,?,?)',rows)

root=Path('/tmp/commontrace-p0-million-tuning-root').read_text().strip()
index_path=Path('/tmp/commontrace-p0-million-tuning-next-index');start=int(index_path.read_text())
results=[];original_bulk_flush=flush
try:
 warm=h.add_facts(root,items(start,1000));assert all(action=='ADD' for _,action in warm)
 start+=1000;index_path.write_text(str(start))
 for label in ['baseline','bulk','bulk_events','bulk_all','bulk_all','bulk_events','bulk','baseline']:
  fs.StatementIndex=original_index if label=='baseline' else StagedIndex
  fs.FactMap.flush=original_flush if label=='baseline' else original_bulk_flush if label=='bulk' else bulk_event_flush
  h.AtomicFact.to_dict=fast_dict if label=='bulk_all' else original_dict
  h._normalize_statement=cached_norm;h._signature=cached_signature;fact_conflicts.slot_key=cached_slot
  cache=FeatureCache() if label=='bulk_all' else None;token=CACHE.set(cache)
  try:
   started=time.perf_counter();admitted=h.add_facts(root,items(start,1000));elapsed=time.perf_counter()-started
  finally:
   if cache is not None:cache.close()
   CACHE.reset(token)
  assert len(admitted)==1000 and all(action=='ADD' for _,action in admitted)
  start+=1000;index_path.write_text(str(start))
  row={'configuration':label,'batch_size':1000,'elapsed_seconds':elapsed,'facts_per_second':1000/elapsed}
  if cache is not None:row['cache']={'hits':cache.hits,'misses':cache.misses,'peak_entries':cache.peak_entries,'peak_weight':cache.peak_weight,'cleared_entries':len(cache.values),'closed':cache.closed}
  results.append(row);print(json.dumps(row),flush=True)
 with fs.transaction(root) as facts:
  assert facts.connection.execute('SELECT l.id FROM lexicon l WHERE l.documents!=(SELECT COUNT(*) FROM postings p WHERE p.term_id=l.id) LIMIT 1').fetchone() is None
finally:
 fs.StatementIndex=original_index;fs.FactMap.flush=original_flush;h.AtomicFact.to_dict=original_dict
 h._normalize_statement=original_norm;h._signature=original_signature;fact_conflicts.slot_key=original_slot
 fs.close_connections(root)
Path('/tmp/commontrace-combined-bulk-diagnostic.json').write_text(json.dumps({'scope':'Private million-copy diagnostic with concurrent frozen suite elsewhere. Not acceptance evidence; staged semantic and general rollback/rebuild contracts unverified.','results':results,'document_frequencies_exact':True,'prototype_source':Path(__file__).read_text()},indent=2)+'\n')
